/**
 * Admin seeding tool for the Elder's catch comments (build plan M27, npc-runtime.md §9.5,
 * architecture §6.3). Only this tool writes the shared `cache/*`: it publishes one line per fish
 * and target language as `cache/lines/{sha256(elderBarkSeedMaterial(fishId, lang))}`, with its
 * translations by native language. A fish the file lacks is generated by the client for that
 * player alone (hybrid task `elderBark`, cloud first) and kept in the player's IndexedDB.
 *
 *   npm run seed:barks -- --prompts <lang> [<nativeLang>]                print the generation prompts
 *   npm run seed:barks -- <barks.json>                                  dry run: validate, list gaps
 *   npm run seed:barks -- <barks.json> --write --project <id>           publish (admin credentials)
 *
 * The barks file: `{ "lang": "es", "barks": { "<fishId>": { "text", "reading"?, "translation": { "en": "…" } } } }`.
 * Run the printed prompts through the cloud model (`gemini-3.8-flash`) with the `elderBark` JSON
 * schema, pick one line per fish and spot-check it before writing.
 *
 * TODO(seeding tool, no milestone yet, see pending.md): run the prompts from here with the admin
 * project, and voice the lines (seeded `tts/` clips).
 */
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { z } from "zod";
import {
  type CachedLine,
  CachedLineSchema,
  elderBarkPrompt,
  elderBarkSeedMaterial,
  FISH,
  FISH_IDS,
  type FishId,
  FirestorePaths,
  getLanguage,
  isFishId,
} from "../../packages/shared/src/index";

export const BarksFileSchema = z.strictObject({
  lang: z.string().min(2).max(20),
  barks: z.record(z.string(), CachedLineSchema),
});

export interface BarksPlan {
  lang: string;
  docs: { fishId: FishId; path: string; doc: CachedLine }[];
  /** Species the file does not cover (generated per player on a miss). */
  missing: FishId[];
}

export const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");

export function planBarksSeed(raw: unknown): BarksPlan {
  const file = BarksFileSchema.parse(raw);
  if (!getLanguage(file.lang)) throw new Error(`unknown language: ${file.lang}`);
  const unknown = Object.keys(file.barks).filter((k) => !isFishId(k));
  if (unknown.length) throw new Error(`unknown fish: ${unknown.join(", ")}`);
  const docs = (Object.entries(file.barks) as [FishId, CachedLine][]).map(([fishId, doc]) => ({
    fishId,
    path: FirestorePaths.cacheEntry("lines", sha256(elderBarkSeedMaterial(fishId, file.lang))),
    doc,
  }));
  return { lang: file.lang, docs, missing: FISH_IDS.filter((id) => !Object.hasOwn(file.barks, id)) };
}

/** One prompt per species. */
export function barkPrompts(lang: string, nativeLang = "en"): { fishId: FishId; prompt: string }[] {
  if (!getLanguage(lang)) throw new Error(`unknown language: ${lang}`);
  if (!getLanguage(nativeLang)) throw new Error(`unknown language: ${nativeLang}`);
  return FISH.map((f) => ({ fishId: f.id, prompt: elderBarkPrompt({ targetLang: lang, nativeLang, fishEnglish: f.englishName, rarity: f.rarity }) }));
}

export async function writeBarksSeed(plan: BarksPlan, projectId: string): Promise<void> {
  const { initializeApp, applicationDefault } = await import("firebase-admin/app");
  const { getFirestore } = await import("firebase-admin/firestore");
  const emulated = Boolean(process.env.FIRESTORE_EMULATOR_HOST);
  const app = initializeApp(emulated ? { projectId } : { projectId, credential: applicationDefault() }, "hellovalley-seed-barks");
  const db = getFirestore(app);
  await Promise.all(plan.docs.map((d) => db.doc(d.path).set(d.doc)));
  console.log(`seeded ${plan.docs.length} Elder comments for ${plan.lang}`);
}

function arg(args: readonly string[], name: string): string | undefined {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
}

export async function main(args: readonly string[]): Promise<number> {
  const promptsFor = arg(args, "--prompts");
  if (promptsFor) {
    const native = args[args.indexOf("--prompts") + 2];
    for (const p of barkPrompts(promptsFor, native && !native.startsWith("--") ? native : "en")) console.log(`--- ${p.fishId}\n${p.prompt}\n`);
    return 0;
  }
  const path = args[0];
  if (!path || path.startsWith("--")) {
    console.error("usage: seed-barks --prompts <lang> [<nativeLang>] | <barks.json> [--write --project <id>]");
    return 2;
  }
  const plan = planBarksSeed(JSON.parse(await readFile(path, "utf8")));
  console.log(`${plan.lang}: ${plan.docs.length} Elder comments, ${plan.missing.length} species missing${plan.missing.length ? ` (${plan.missing.join(", ")})` : ""}`);
  if (!args.includes("--write")) {
    console.log("dry run: nothing written (add --write --project <id>)");
    return 0;
  }
  const projectId = arg(args, "--project");
  if (!projectId) {
    console.error("--write needs --project <id>");
    return 2;
  }
  if (!process.env.FIRESTORE_EMULATOR_HOST && !process.env.GOOGLE_APPLICATION_CREDENTIALS) {
    console.error("--write needs GOOGLE_APPLICATION_CREDENTIALS (an admin service account) or the emulators");
    return 2;
  }
  await writeBarksSeed(plan, projectId);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (error: unknown) => {
      console.error(error instanceof Error ? error.message : error);
      process.exit(1);
    },
  );
}
